// drills.js — game data keyed by ticket n (see tickets.js).
// lies: false-but-plausible statements (the traps). cloze: "[[answer|alt|alt]]" blanks. steps: correct order, the UI shuffles.
window.DRILLS = {
1:{"lies":{"ru":["Токен — это один символ текста.","В одном токене примерно четыре слова."],"en":["A token is a single character of text.","One token is roughly four words."]},"cloze":{"ru":["Программа, которая разбивает текст на токены и сопоставляет им номера, называется [[токенайзер|токенизатор]].","BPE расшифровывается как [[Byte Pair Encoding|byte pair encoding]] — кодирование пар байтов.","Число токенов полного запроса проверяют для выбранной [[модели]]; постоянного коэффициента для русского текста [[нет]]."],"en":["A program that splits text into tokens and maps them to IDs is a [[tokenizer|tokeniser]].","BPE stands for [[Byte Pair Encoding|byte pair encoding]].","Count the complete request for the selected [[model]]; a universal Russian token multiplier does [[not exist]]."]}},
2:{"lies":{"ru":["В прямом Claude API слишком большой вход всегда автоматически обрезается до окна.","На текущих моделях Claude запрос, где промпт помещается, но вход плюс max_tokens больше окна, отклоняется до генерации."],"en":["The direct Claude API always automatically truncates oversized input to fit the window.","On current Claude models, a request whose prompt fits but whose input plus max_tokens exceeds the window is rejected before generation."]},"cloze":{"ru":["В прямом Claude API вход больше окна приводит к ошибке 400 [[до|раньше]] начала генерации.","На Claude 4.5+, если переполняет только вход плюс max_tokens, запрос принимается, а если генерация дойдёт до границы окна, она остановится со stop_reason [[model_context_window_exceeded]].","stop_reason равный [[max_tokens]] значит «обрезано», а не «готово»."],"en":["In the direct Claude API, input exceeding the window produces a 400 error [[before]] generation.","On Claude 4.5+, if only input plus max_tokens overflows, the request is accepted, and if generation hits the window it stops with stop_reason [[model_context_window_exceeded]].","A stop_reason of [[max_tokens]] means truncated, not finished."]}},
3:{"lies":{"ru":["Входные и выходные токены стоят одинаково, разница только в количестве.","Сокращение системного промпта — главный рычаг экономии в агенте."],"en":["Input and output tokens cost the same; only the count differs.","Trimming the system prompt is the main cost lever in an agent."]},"cloze":{"ru":["На этапе prefill многие вычисления над известным входом выполняются [[параллельно|параллельно друг другу]].","Обычная генерация выхода [[последовательная|последовательна]]: следующий токен зависит от уже выбранных.","Для цены задачи нужно сложить расходы [[всех|каждого из]] её вызовов, включая повторы."],"en":["During prefill, many computations over the known input run in [[parallel]].","Ordinary output generation is [[sequential]]: the next token depends on those already chosen.","Task cost includes [[all]] its calls, including retries."]},"steps":{"ru":{"title":"Как проверить оптимизацию расходов?","items":["Собрать расходы и качество исходных задач","Разделить расходы по моделям, входу, выходу, кэшу и повторам","Выбрать изменение на основе найденной причины","Сравнить варианты на одинаковом наборе задач","Проверить и стоимость, и качество результата"]},"en":{"title":"How do you evaluate a cost optimization?","items":["Record baseline task cost and quality","Break down models, input, output, cache usage and retries","Choose a change based on the observed cause","Compare variants on the same task set","Check both cost and result quality"]}}},
4:{"lies":{"ru":["temperature = 0 гарантирует одинаковый ответ на одинаковый запрос.","Высокая temperature добавляет модели знаний."],"en":["temperature = 0 guarantees the same answer for the same request.","Higher temperature gives the model more knowledge."]},"cloze":{"ru":["Temperature [[делит|divides]] логиты перед [[softmax]] — это весь механизм.","temp 0 реализован как [[greedy|жадное]] декодирование: всегда берётся топ-токен.","top_p набирает токены сверху, пока суммарная масса не достигнет [[p]], и это адаптивно; top_k всегда берёт ровно [[k]]."],"en":["Temperature [[divides]] the logits before the [[softmax]] — that's the entire mechanism.","temp 0 is implemented as [[greedy]] decoding: always take the top token.","top_p keeps tokens from the top until the mass reaches [[p]] — adaptive; top_k always takes exactly [[k]]."]}},
5:{"lies":{"ru":["Системный промпт — это жёсткая граница: модель физически не может его нарушить.","Данные пользователя лучше интерполировать в system, чтобы модель их точно учла."],"en":["The system prompt is a hard boundary: the model physically cannot violate it.","Per-user data belongs in the system prompt so the model definitely takes it into account."]},"cloze":{"ru":["System держат [[статичным|static|неизменным]], иначе [[prompt caching|кэш|кэширование]] никогда не сработает.","Модель обучена [[иерархии инструкций|instruction hierarchy]]: system выше user, user выше результатов инструментов.","Системный промпт — это [[тенденция|склонность|prior]] из обучения, а не система прав."],"en":["Keep system [[static|stable]], or [[prompt caching|caching|the cache]] never hits.","Models are trained on an [[instruction hierarchy|hierarchy]]: system outranks user, user outranks tool results.","The system prompt is a trained [[tendency|prior]], not a permission system."]}},
6:{"lies":{"ru":["Prompt injection — это когда пользователь пишет «ignore previous instructions»; на этом всё.","Хорошие разделители вокруг документа полностью закрывают injection."],"en":["Prompt injection is when the user types 'ignore previous instructions' — that's the whole thing.","Good delimiters around the document fully close the injection hole."]},"cloze":{"ru":["Опасный вид — [[indirect|непрямой|косвенный]] injection: инструкция сидит в странице или PDF, которые агент достал сам.","Надёжная граница существует только [[вне|снаружи]] модели — в коде, который исполняет действия.","Что вернула модель — это [[недоверенный|untrusted]] ввод: валидируй по схеме."],"en":["The dangerous kind is [[indirect]] injection: the instruction sits in a page or PDF the agent fetched itself.","A reliable boundary only exists [[outside]] the model — in the code that executes actions.","What the model returns is [[untrusted]] input: validate it against a schema."]}},
7:{"lies":{"ru":["Для инструмента, который я описал сам, модель сама вызывает функцию и получает результат.","Описание инструмента — это документация для людей; модель смотрит на схему."],"en":["For a tool I define myself, the model calls the function itself and receives the result.","The tool description is documentation for humans; the model looks at the schema."]},"cloze":{"ru":["Для моих инструментов модель возвращает [[намерение|intent]]: имя инструмента и аргументы; исполняет [[мой код|код]].","Результат кладётся обратно как [[tool_result]] с тем же [[tool_use_id]].","Цикл идёт, пока stop_reason не перестанет быть [[tool_use]]."],"en":["For my own tools, the model returns an [[intent]]: a tool name and arguments; [[my code|the code]] executes it.","The result goes back as a [[tool_result]] carrying the same [[tool_use_id]].","The loop runs until stop_reason is no longer [[tool_use]]."]}},
8:{"lies":{"ru":["Агент гарантированно остановится сам, когда инструмент начнёт падать, поэтому лимит шагов не нужен.","Ошибку инструмента надо бросать исключением, чтобы агент не продолжал с плохими данными."],"en":["The agent is guaranteed to stop on its own once the tool starts failing, so a step cap is unnecessary.","A tool error should be thrown as an exception so the agent doesn't continue with bad data."]},"cloze":{"ru":["Четыре стоп-условия: финальный ответ, [[потолок шагов|step cap|max steps]], невосстановимая ошибка, чекпоинт для [[человека|human]].","Ошибку инструмента возвращаю в tool_result с [[is_error]]: true — модель читает и идёт другим путём.","Учёт стоимости висит на событии [[exit]] процесса, но при [[SIGKILL]], OOM или нативном abort не выполнится ничего."],"en":["Four stop conditions: final answer, the [[step cap|iteration cap|max steps]], an unrecoverable error, a [[human]] checkpoint.","I return a tool error inside tool_result with [[is_error]]: true — the model reads it and tries another route.","Cost accounting hangs off the process [[exit]] event, but nothing runs on [[SIGKILL]], an OOM kill or a native abort."]}},
9:{"lies":{"ru":["Кэшируют Q, потому что запрос повторяется чаще всего.","Prompt caching — это чтобы не платить за один и тот же текст дважды, и на этом всё."],"en":["Q gets cached because the query repeats most often.","Prompt caching is just so you don't pay for the same text twice, nothing more."]},"cloze":{"ru":["K и V токена зависят только от него и от того, что [[до|перед|раньше]] него — поэтому их можно сохранить.","[[Q]] каждый раз новый: он сравнивает текущий токен с постоянными K/V.","Prompt caching продлевает жизнь [[KV]]-состояния между запросами: запись дороже, чтение почти [[бесплатно|даром]]."],"en":["A token's K and V depend only on itself and what came [[before]] it — so they can be stored.","[[Q]] is fresh every time: it compares the current token against the fixed K/V.","Prompt caching persists [[KV]] state across requests: writes cost more, reads are nearly [[free]]."]}},
10:{"lies":{"ru":["Модель помнит предыдущие вызовы, если использовать тот же API-ключ.","Summarization — единственный способ справиться с переполнением контекста."],"en":["The model remembers previous calls if you use the same API key.","Summarization is the only way to deal with context overflow."]},"cloze":{"ru":["Модель не помнит [[ничего|ничего между вызовами]]: помнит мой массив [[messages]].","Вход каждого запроса растёт [[линейно]] с историей, поэтому суммарная стоимость разговора растёт [[квадратично]].","Лестница от дешёвого: [[sliding window|скользящее окно]] → summarization → RAG → map-reduce, а кэш — вместе с ними; выбираю самое дешёвое из достаточного."],"en":["The model remembers [[nothing]]: what remembers is my [[messages]] array.","Each request's input grows [[linearly]] with the history, so total cost over the conversation grows [[quadratically]].","The ladder, cheapest first: [[sliding window]] → summarization → RAG → map-reduce, with caching alongside; pick the cheapest that suffices."]}},
11:{"lies":{"ru":["SSE — это двусторонний канал вроде WebSocket.","Общая задержка ответа при стриминге меньше, чем без него."],"en":["SSE is a bidirectional channel like WebSocket.","Total response latency is lower with streaming than without."]},"cloze":{"ru":["SSE — это HTTP-ответ с content-type [[text/event-stream]], который сервер не закрывает.","TextDecoder с флагом [[stream: true|stream:true|stream]] — иначе чанк режет UTF-8 пополам.","Стриминг улучшает время до [[первого токена|first token]], а не общую задержку."],"en":["SSE is an HTTP response with content-type [[text/event-stream]] that the server keeps open.","TextDecoder with [[stream: true|stream:true|stream]] — otherwise a chunk splits UTF-8 mid-character.","Streaming improves time to [[first token]], not total latency."]}},
12:{"lies":{"ru":["JSON mode гарантирует, что значения в ответе правдивы.","Если провайдер отдал strict JSON, своя валидация не нужна."],"en":["JSON mode guarantees the values in the response are true.","If the provider returned strict JSON, your own validation is unnecessary."]},"cloze":{"ru":["Без [[strict: true|strict]] схема инструмента — лишь подсказка; с ним генерацию ограничивает [[constrained decoding]].","[[tool_choice]] с именем принуждает к этому инструменту, но только на моделях, где поддерживается [[принудительный вызов|принудительный вызов инструмента]].","При ошибке — retry с текстом [[ошибки валидации|ошибки]], максимум [[2|два]] повтора, потом fallback."],"en":["Without [[strict: true|strict]], a tool schema is only guidance; with it, generation is limited by [[constrained decoding]].","[[tool_choice]] with a name forces that tool, but only on models that support [[forced tool use|forcing a tool]].","On failure, retry with the [[validation error|error]] appended, [[2|two]] retries max, then fallback."]}},
13:{"lies":{"ru":["Лучшая стратегия — самая сильная модель на каждом шаге.","Деньги в агенте всегда уходят в основном на модель, которая пишет финальный ответ."],"en":["The best strategy is the strongest model on every step.","The money in an agent always goes mostly to the model that writes the final answer."]},"cloze":{"ru":["По умолчанию — [[Sonnet]]; [[Haiku]] — для массовых простых шагов; Opus — где качество и есть продукт.","Роутинг: дешёвая модель [[ужимает|дистиллирует|сжимает]] страницы до того, как их видит дорогая.","Понижаешь модель только после [[эвала|eval|evaluation]] на golden set."],"en":["Default is [[Sonnet]]; [[Haiku]] for bulk simple steps; Opus where quality is the product.","Routing: a cheap model [[distills|shrinks|summarises]] pages before the expensive one sees them.","You downgrade a model only after an [[eval|evaluation]] on a golden set."]}},
14:{"lies":{"ru":["ReAct — это просто «думай по шагам», инструменты никто не исполняет.","Каждая итерация цикла отправляет только новое наблюдение, поэтому стоимость постоянна."],"en":["ReAct is just 'think step by step' — no tools are executed.","Each loop iteration sends only the new observation, so the cost stays constant."]},"cloze":{"ru":["ReAct: [[Reason|рассуждение]] плюс [[Act|действие]] — модель думает, выбирает инструмент, получает наблюдение, думает снова.","Если stop_reason равен [[tool_use]] — исполняю и кладу [[tool_result]]; если [[end_turn]] — это финальный ответ.","Обязательны: потолок [[шагов|steps|итераций]] и [[бюджет|budget]] по деньгам."],"en":["ReAct: [[Reason]] plus [[Act]] — the model thinks, picks a tool, observes, thinks again.","If stop_reason is [[tool_use]] I execute and append a [[tool_result]]; if [[end_turn]], that's the final answer.","Non-negotiable: a [[step cap|iteration cap]] and a spending [[budget]]."]}},
15:{"lies":{"ru":["Если корпус помещается в контекст, RAG в принципе не может повысить точность.","Окна в миллион токенов делают RAG ненужным."],"en":["If the corpus fits in context, RAG can't possibly improve accuracy.","Million-token windows make RAG unnecessary."]},"cloze":{"ru":["Первый вопрос всегда: сколько корпус в [[токенах|tokens]]?","Пять причин для RAG: не помещается, [[цена|стоимость|cost]], свежесть, точность, [[права доступа|permissions]].","Модель теряет [[середину|middle]] длинного контекста — релевантная выборка отвечает точнее полной свалки."],"en":["The first question is always: how many [[tokens]] is the corpus?","Five reasons for RAG: doesn't fit, [[cost]], freshness, precision, [[access control|permissions]].","The model loses the [[middle]] of a long context — a relevant selection beats a full dump."]}},
16:{"lies":{"ru":["Чем больше кусок, тем точнее эмбеддинг.","Overlap нужен просто чтобы кусков было больше; контекст на границе не важен."],"en":["The bigger the chunk, the more precise the embedding.","Overlap exists just to produce more chunks; boundary context doesn't matter."]},"cloze":{"ru":["Обычная отправная точка — кусок в [[256-512|256–512]] токенов и перекрытие [[10-25%|10–25%]].","Overlap нужен, чтобы факт у [[границы|boundary]] не оказался разрезан на два куска.","Правильность chunking проверяю через [[recall@k|recall at k|recall]] на золотом наборе, а не чтением."],"en":["A common starting chunk is [[256-512|256–512]] tokens, with [[10-25%|10–25%]] overlap.","Overlap exists so a fact near a [[boundary]] isn't split across two chunks.","I check chunking with [[recall@k|recall at k|recall]] on a golden set, not by reading."]}},
17:{"lies":{"ru":["Запрос и документы можно эмбеддить любыми двумя несвязанными моделями — расстояния всё равно сопоставимы.","Cosine и dot product дают разные результаты на нормализованных векторах."],"en":["Query and documents can be embedded with any two unrelated models; distances are still comparable.","Cosine and dot product give different results on normalised vectors."]},"cloze":{"ru":["Запрос и документы обычно эмбеддятся [[одной|одной и той же|той же]] моделью — несвязанные модели делают расстояния бессмысленными.","На [[нормализованных|единичных]] векторах cosine и dot product — одно и то же, dot просто дешевле.","Точные идентификаторы семантика не различает — добавляю гибрид с [[BM25]]."],"en":["Query and documents are normally embedded with the [[same]] model — unrelated models make distances meaningless.","On [[normalised|unit|normalized]] vectors cosine and dot product are identical; dot is just cheaper.","Semantics can't separate exact identifiers — I add hybrid search with [[BM25]]."]}},
18:{"lies":{"ru":["Реранкер — это повторная сортировка кандидатов по тому же score.","k = 1 — оптимально: меньше шума в контексте."],"en":["A reranker is re-sorting the candidates by the same score.","k = 1 is optimal: less noise in the context."]},"cloze":{"ru":["k обычно [[5-20|5–20]]; выбираю по [[recall@k|recall at k|recall]] на золотом наборе.","Реранкер — это [[cross-encoder]]: читает запрос и кандидата [[вместе]].","Схема: достать широкий пул, [[переранжировать]], оставить верхние — у Anthropic из [[150|ста пятидесяти]] оставляли 20."],"en":["k is usually [[5-20|5–20]]; I pick it by [[recall@k|recall at k|recall]] on a golden set.","A reranker is a [[cross-encoder]]: it reads query and candidate [[together]].","The pattern: retrieve a wide pool, [[rerank|re-rank]], keep the top few — Anthropic went from [[150|a hundred fifty|one hundred fifty]] to 20."]}},
19:{"lies":{"ru":["Если ответ плохой, это почти всегда вина модели-генератора.","Эвал на 30 вопросах слишком мал, чтобы что-то значить."],"en":["If the answer is bad, it's almost always the generator model's fault.","An eval of 30 questions is too small to mean anything."]},"cloze":{"ru":["Четыре стадии отказа: ингестия, [[retrieval miss|промах ретривера]], ранжирование, [[генерация|generation]].","[[Faithfulness|Groundedness]] — каждое утверждение ответа подтверждено вытащенным контекстом.","Метрики retrieval — дешёвые и [[детерминированные|детерминистичные]]; метрики генерации — дорогие и шумные."],"en":["Four failure stages: ingestion, [[retrieval miss]], ranking, [[generation]].","[[Faithfulness|Groundedness]] — every claim in the answer is supported by retrieved context.","Retrieval metrics are cheap and [[deterministic]]; generation metrics are expensive and noisy."]}},
20:{"lies":{"ru":["Браузер может ходить в API модели напрямую, если ключ спрятать в env-переменную фронтенда.","Клиент присылает всю историю, серверу так проще."],"en":["The browser can call the model API directly if the key is hidden in a frontend env variable.","The client sends the whole history; it's simpler for the server."]},"cloze":{"ru":["Ключ API живёт только на [[сервере|server|бэкенде]]; браузер ходит в мой [[API route|роут]].","Историю восстанавливает [[сервер]] по id разговора — клиентской истории нельзя доверять.","Рендер батчу через [[requestAnimationFrame|rAF]], а не на каждый токен."],"en":["The API key lives only on the [[server|backend]]; the browser calls my [[API route|route]].","The [[server]] rebuilds history from the conversation id — client history can't be trusted.","I batch renders on [[requestAnimationFrame|rAF]], not per token."]}},
21:{"lies":{"ru":["Отфильтровать тенантов в коде приложения после выборки top-k — достаточно надёжно.","Обновление документа — просто добавить новые куски; старые не мешают."],"en":["Filtering tenants in app code after retrieving the top-k is safe enough.","Updating a document is just adding new chunks; the old ones don't matter."]},"cloze":{"ru":["Фильтр по тенанту — [[внутри запроса|в самом запросе]], а не в коде после выдачи.","pgvector с индексом [[HNSW]] — мой дефолт, когда Postgres уже есть.","Обновление: перечанкить и удалить старые куски по [[id документа|document id|doc id]]; поле [[версии|version]] спасает от устаревших."],"en":["The tenant filter goes [[inside the query|in the query]], never in app code after retrieval.","pgvector with an [[HNSW]] index is my default when Postgres is already there.","Updates: re-chunk and delete old chunks by [[document id|doc id]]; a [[version]] field prevents stale chunks."]}},
22:{"lies":{"ru":["Prompt caching решает проблему больших входов целиком.","Первый шаг оптимизации — сжать системный промпт."],"en":["Prompt caching solves the large-input problem completely.","The first optimisation step is to compress the system prompt."]},"cloze":{"ru":["Сначала [[измеряю|инструментирую|measure]], потом трогаю: модель, токены, фича, пользователь на каждый вызов.","Самый большой рычаг — [[роутинг|routing]] моделей: массовым шагам флагман редко нужен.","Кэш чинит [[пересылку|resending]], а не объём; timestamp в начале system prompt [[ломает|убивает]] кэш."],"en":["[[Measure|Instrument]] first, touch second: model, tokens, feature, user on every call.","The biggest lever is model [[routing]]: bulk steps rarely need the flagship.","Caching fixes [[resending]], not volume; a timestamp at the top of the system prompt [[breaks|kills]] the cache."]}},
23:{"lies":{"ru":["Хорошее self-intro начинается с первого места работы и идёт по хронологии.","Слово «transitioning» звучит честно и располагает интервьюера."],"en":["A good self-intro starts with your first job and goes chronologically.","The word 'transitioning' sounds honest and wins the interviewer over."]},"cloze":{"ru":["По порядку: кто я сейчас, что [[строю|делаю]] последний год, что [[ищу|хочу]].","Никогда: career switcher, learning AI, [[transitioning]].","Заканчиваю не хронологией, а [[запросом|ask|посадкой]]: какую роль ищу и почему."],"en":["In order: who I am now, what I've [[built|been building]] this year, what I'm [[looking for|after]].","Never: career switcher, learning AI, [[transitioning]].","I end on the [[ask|landing]], not on chronology: which role and why."]}},
24:{"lies":{"ru":["Лучший ответ на «почему AI» — про страсть и давний интерес.","Переход из фронта в AI — это шаг вниз, и лучше это признать сразу."],"en":["The best answer to 'why AI' is about passion and long-standing interest.","Moving from frontend to AI is a step down, and it's best to admit that up front."]},"cloze":{"ru":["Работа с LLM сейчас выглядит как фронт в [[2016]]: молодая экосистема, нет учебника.","RAG-проект живёт на сайте с эвалом [[9/9|девять из девяти]].","На research-агенте я измерил prompt caching: [[1.5|полтора]] раза на одном прогоне."],"en":["Building with LLMs feels like frontend in [[2016]]: young ecosystem, no playbook.","The RAG project is live with a [[9/9|nine out of nine]] eval score.","On the research agent I measured prompt caching at [[1.5|one and a half]] times on a single run."]}},
25:{"lies":{"ru":["В STAR-истории важнее всего подробно описать ситуацию и контекст компании.","«Мы сделали» звучит скромнее и лучше воспринимается."],"en":["In a STAR story the most important part is describing the situation and company context in detail.","'We did' sounds humbler and lands better."]},"cloze":{"ru":["Ситуации и задаче — по [[1-2|одному-два|1–2]] предложения; больше всего времени — на [[действие|action]].","В результате обязана быть [[цифра|число]] или наблюдаемый факт.","История провала: что пошло не так → что сделал → что изменил [[навсегда|permanently]]."],"en":["Situation and task get [[1-2|one or two|1–2]] sentences each; most of the time goes to the [[action]].","The result must contain a [[number]] or an observable fact.","A failure story: what went wrong → what I did → what I changed [[permanently]]."]}},
26:{"lies":{"ru":["setTimeout(0) выполнится раньше Promise.then, потому что ноль — это сразу.","Стрелочная функция — это просто короткий синтаксис, this у неё такой же."],"en":["setTimeout(0) runs before Promise.then because zero means immediately.","An arrow function is just shorter syntax; its this behaves the same."]},"cloze":{"ru":["[[Микрозадачи|microtasks]] всегда раньше макрозадач: очередь опустошается целиком.","forEach с await не ждёт, потому что forEach [[игнорирует|не смотрит на]] возвращаемое значение колбэка.","Стрелка берёт this [[лексически|из окружения]] и не имеет своего."],"en":["[[Microtasks]] always run before macrotasks: the queue is drained entirely.","forEach with await doesn't wait because forEach [[ignores]] the callback's return value.","An arrow takes this [[lexically]] and has none of its own."]}},
27:{"lies":{"ru":["React сопоставляет хуки по имени, поэтому условия ломают только одноимённые.","useMemo везде по умолчанию делает приложение быстрее."],"en":["React matches hooks by name, so conditions only break same-named hooks.","useMemo everywhere by default makes the app faster."]},"cloze":{"ru":["React хранит состояние хуков в списке и сопоставляет по [[порядку вызова|порядку|call order]].","Cleanup вызывается перед [[следующим|next]] запуском эффекта и при размонтировании.","key равный [[index|индексу]] ломается при reorder: React переиспользует состояние не тех элементов."],"en":["React stores hook state in a list and matches by [[call order|order]].","Cleanup runs before the [[next]] run of the effect and on unmount.","key equal to [[index]] breaks on reorder: React reuses the wrong elements' state."]}},
28:{"lies":{"ru":["Fine-tuning — правильный первый шаг, если модель не знает нужных фактов.","RAG требует переобучения модели при каждом обновлении источника."],"en":["Fine-tuning is the right first move if the model doesn't know the facts you need.","RAG requires retraining the model every time the source data updates."]},"cloze":{"ru":["Knowledge gap чинится через [[RAG]], behavior gap — сначала через [[prompt engineering|промпт]].","Обновление источника в RAG — это [[re-index|переиндексация]], а не re-train.","Fine-tuning без [[eval-сьюта|eval harness]] — это дообучение вслепую."],"en":["A knowledge gap gets fixed with [[RAG]], a behavior gap first with [[prompt engineering|prompting]].","Updating RAG's source is a [[re-index]], not a re-train.","Fine-tuning without an [[eval harness|eval suite]] is fine-tuning blind."]}},
29:{"lies":{"ru":["Лучший ответ на «твоя слабость» — назвать сильную сторону в замаскированном виде.","История про конфликт сильнее без описания сути разногласия."],"en":["The best answer to 'what's your weakness' is a strength in disguise.","A conflict story is stronger without describing what the actual disagreement was about."]},"cloze":{"ru":["Слабость без [[механизма компенсации|способа с этим справляться]] — это не ответ, а уклонение.","Фидбэк без [[изменения поведения|конкретного действия]] — это просто история, не рост.","Конфликт: Situation — Task — Action — [[Result]]."],"en":["A weakness with no [[compensating mechanism|way of coping with it]] is a dodge, not an answer.","Feedback without a [[behavior change|concrete action]] is just a story, not growth.","Conflict: Situation — Task — Action — [[Result]]."]}},
30:{"lies":{"ru":["Лучший способ показать лидерство без власти — говорить громче своего мнения на митингах.","«Почему уходишь сейчас» лучше отвечать через недовольство текущим местом — это честно."],"en":["The best way to show leadership without authority is being the loudest voice with an opinion in meetings.","The honest way to answer 'why leaving now' is through dissatisfaction with your current place."]},"cloze":{"ru":["Правоту решения, продвинутого без формальной власти, доказывают [[метрика]] или [[инцидент]], который оно предотвратило, а не «я предложил».","«Почему уходишь» — формула: ценишь → [[что не даёт расти|не растёт в нужном направлении]] → почему именно сейчас.","Быстрое обучение: честный ответ и [[питч пивота|pivot pitch]] — одна и та же история."],"en":["A decision pushed without formal authority is proven right by a [[metric]] or an [[incident]] it prevented, not by 'I suggested it'.","'Why leaving' formula: what you value → [[what doesn't let you grow|the growth cap]] → why now specifically.","Learning fast: the honest answer and the [[pivot pitch]] are the same story."]}},
31:{"lies":{"ru":["Браузер отрисовывает кадр после каждой задачи, так что у каждого вызова setTimeout своя отрисовка.","await уже выполненного промиса в цикле даёт браузеру отрисовать кадр между итерациями."],"en":["The browser renders a frame after every single task, so each setTimeout callback gets its own paint.","Awaiting an already-resolved promise in a loop gives the browser a chance to paint between iterations."]},"cloze":{"ru":["После каждой задачи браузер выполняет всю очередь [[микрозадач]] до конца, прежде чем рисовать или брать следующую задачу.","Задача дольше [[50|пятидесяти]] миллисекунд считается long task и задерживает обработку ввода.","Чтобы разбить тяжёлую работу, я отдаю управление через setTimeout или [[scheduler.yield|scheduler.yield()]], а вычислительную работу выношу в [[Web Worker|воркер]]."],"en":["After each task, the browser drains the entire [[microtask]] queue before it can render or pick the next task.","A task that runs longer than [[50|fifty]] milliseconds is a long task and delays input handling.","To break up heavy work I yield with setTimeout or [[scheduler.yield|scheduler.yield()]], and move CPU-bound work to a [[Web Worker|worker]]."]}},
32:{"lies":{"ru":["Замыкание хранит копию значения переменной на момент создания функции.","Если обернуть записи кэша в WeakRef, они гарантированно освободятся сразу, как только их больше никто не использует."],"en":["A closure stores a copy of the variable's value at the moment the function is created.","Wrapping cache entries in WeakRef guarantees they are freed as soon as nothing else uses them."]},"cloze":{"ru":["Замыкание захватывает [[привязку]] переменной, а не снимок её значения.","Элемент, удалённый со страницы, но всё ещё доступный из JavaScript, это [[detached|отсоединённый]] DOM-узел.","В heap snapshot панель [[Retainers|удерживающих ссылок]] показывает цепочку ссылок, которая держит объект живым."],"en":["A closure captures the variable [[binding]], not a snapshot of its value.","An element removed from the page but still referenced from JavaScript is a [[detached]] DOM node.","In a heap snapshot the [[retainers|retainer]] panel shows the chain of references keeping an object alive."]}},
33:{"lies":{"ru":["Когда Promise.all отклоняется, остальные промисы автоматически отменяются.","400 Bad Request стоит повторять с экспоненциальной задержкой, потому что сервер может восстановиться."],"en":["When Promise.all rejects, the remaining promises are cancelled automatically.","A 400 Bad Request is worth retrying with exponential backoff because the server may recover."]},"cloze":{"ru":["Promise.[[any]] отдаёт первый успех и отклоняется с [[AggregateError]], только если упали все.","Чтобы отменить fetch, я передаю ему signal от [[AbortController]] и вызываю abort.","Повторы делаю с экспоненциальной [[задержкой|паузой]] и [[jitter|случайным разбросом]] — для 408, 429, 5xx и сетевых ошибок."],"en":["Promise.[[any]] resolves with the first success and rejects with an [[AggregateError]] only if all fail.","To cancel a fetch, I pass it the signal from an [[AbortController]] and call abort.","Retries use exponential [[backoff|back-off]] with [[jitter|randomization]], for 408, 429, 5xx and network errors."]}},
34:{"lies":{"ru":["Стрелочная функция берёт this от того, кто её вызывает, поэтому obj.arrow() привязывает this к obj.","structuredClone сохраняет прототип экземпляров класса, так что методы на копии продолжают работать."],"en":["An arrow function takes this from whoever calls it, so obj.arrow() binds this to obj.","structuredClone keeps the prototype of class instances, so methods still work on the copy."]},"cloze":{"ru":["Стрелочные функции берут this [[лексически]] из окружающей области и не могут вызываться через [[new]].","x == null истинно для null и [[undefined]], поэтому это единственное намеренное использование ==.","Spread делает [[поверхностную]] копию, а [[structuredClone]] делает глубокую, но бросает ошибку на функциях."],"en":["Arrow functions take this [[lexically]] from the enclosing scope and can't be called with [[new]].","x == null is true for null and [[undefined]], which is why it's the one intentional use of ==.","Spread makes a [[shallow]] copy, while [[structuredClone]] makes a deep one but throws on functions."]}},
35:{"lies":{"ru":["В ESM импортирующий модуль получает копию значения на момент импорта, поэтому последующие изменения экспорта он не видит.","Актуальные версии Node всегда бросают ERR_REQUIRE_ESM, когда CommonJS-код делает require пакета, который есть только в ESM."],"en":["In ESM the importer gets a copy of the value at import time, so later changes to the export aren't visible to it.","Current Node versions always throw ERR_REQUIRE_ESM when CommonJS code requires an ESM-only package."]},"cloze":{"ru":["Поскольку импорты ESM [[статические]], бандлер может делать [[tree shaking|tree-shaking]].","Начиная с Vite 8, и пребандлинг зависимостей, и продакшен-сборка работают на [[Rolldown]].","Динамический [[import()|import]] — это точка разреза, и бандлер выносит модуль в отдельный [[чанк|chunk]]."],"en":["Because ESM imports are [[static]], the bundler can do [[tree shaking|tree-shaking]].","Since Vite 8, dependency pre-bundling and the production build both run on [[Rolldown]].","A dynamic [[import()|import]] is a split point, and the bundler emits that module as a separate [[chunk]]."]}},
36:{"lies":{"ru":["TypeScript сообщает о лишних свойствах всегда, когда у объекта есть ключи, которых нет в целевом типе, даже если объект передан через переменную.","Компилятор проверяет тело пользовательского type guard вида x is User, поэтому неверная проверка внутри даст ошибку компиляции."],"en":["TypeScript reports extra properties whenever an object has keys the target type doesn't declare, even when the object is passed through a variable.","The compiler verifies the body of a user-defined type guard like x is User, so a wrong check inside it is a compile error."]},"cloze":{"ru":["Проверка лишних свойств срабатывает только на [[свежих объектных литералах|объектных литералах]], а передача через переменную её обходит.","В отличие от any, значение типа [[unknown]] нельзя использовать, пока его не сузишь.","В ветке default исчерпывающего switch оставшееся значение присваивают переменной типа [[never]], и новый член объединения ломает компиляцию."],"en":["Excess property checks only apply to [[fresh object literals|object literals]], and passing through a variable first bypasses them.","Unlike any, a value of type [[unknown]] can't be used until you narrow it.","In the default branch of an exhaustive switch, the leftover value is assigned to a variable of type [[never]], so a new union member breaks compilation."]}},
37:{"lies":{"ru":["Обёртка обеих сторон в квадратные скобки, [T] extends [U], как раз и заставляет условный тип распределяться по каждому члену объединения.","Запись const config = {...} as Config заставляет TypeScript проверить, что все обязательные поля Config на месте."],"en":["Wrapping both sides in brackets, [T] extends [U], is what makes a conditional type distribute over each union member.","Writing const config = {...} as Config makes TypeScript verify that every required field of Config is present."]},"cloze":{"ru":["В getProperty<T, K extends [[keyof T]]> возвращаемый тип T[K] получается через [[indexed access|доступ по индексу]].","Условный тип распределяется по объединению, только если проверяемый тип — [[голый|необёрнутый]] параметр типа.","[[satisfies]] проверяет значение против типа, но сохраняет его [[выведенный]] тип."],"en":["In getProperty<T, K extends [[keyof T]]>, the return type T[K] is an [[indexed access]] type.","A conditional type distributes over a union only when the checked type is a [[naked|bare]] type parameter.","[[satisfies]] checks a value against a type but keeps its [[inferred]] type."]}},
38:{"lies":{"ru":["Если привести результат response.json() к типу User через as, TypeScript проверит форму ответа в runtime.","noUncheckedIndexedAccess и exactOptionalPropertyTypes оба включаются вместе с strict: true."],"en":["Casting the result of response.json() to User with as makes TypeScript check the response shape at runtime.","noUncheckedIndexedAccess and exactOptionalPropertyTypes are both turned on by strict: true."]},"cloze":{"ru":["Вывод типа через [[z.infer]] делает zod-схему [[единственным источником правды|источником правды]].","[[safeParse]] возвращает объект результата вместо исключения, а [[parse]] бросает ошибку на невалидных данных.","Для вызова инструмента строки partial_json накапливают и парсят только по событию [[content_block_stop]]."],"en":["Deriving the type with [[z.infer]] makes the zod schema the [[single source of truth|source of truth]].","[[safeParse]] returns a result object instead of throwing, while [[parse]] throws on invalid input.","For tool calls, accumulate the partial_json strings and parse them only on [[content_block_stop]]."]}},
39:{"lies":{"ru":["Мутация ref.current перерендеривает компонент так же, как вызов setState.","Индекс в качестве key безопасен, если содержимое элементов списка уникально."],"en":["Mutating ref.current re-renders the component, just like calling setState does.","Using the index as key is safe as long as the items' contents are unique."]},"cloze":{"ru":["Фаза [[render|рендера]] должна быть чистой; изменения в DOM применяются в фазе [[commit|коммита]].","React узнаёт каждый хук по [[порядку вызова|порядку вызовов]], поэтому хуки нельзя вызывать внутри условий.","Начиная с React [[18]] (при createRoot) обновления внутри Promise и setTimeout автоматически объединяются в один рендер."],"en":["The [[render]] phase must be pure; DOM changes are applied in the [[commit]] phase.","React identifies each hook by its [[call order|order of calls]], which is why hooks can't be called inside conditions.","Since React [[18]] with createRoot, updates inside promises and setTimeout are batched automatically."]}},
40:{"lies":{"ru":["Strict Mode запускает эффекты дважды и в продакшене, поэтому каждый запрос нужно дедуплицировать.","useLayoutEffect выполняется после отрисовки кадра, поэтому он лучшее место для загрузки данных."],"en":["Strict Mode runs effects twice in production too, so every request has to be deduplicated.","useLayoutEffect runs after the browser paints, which makes it the better place for data fetching."]},"cloze":{"ru":["Когда эффект перезапускается, React сначала вызывает [[cleanup|функцию очистки]] предыдущего эффекта.","Чтобы по-настоящему отменить запрос, я передаю в fetch signal от [[AbortController]] и вызываю abort в cleanup.","useEffectEvent стабилен начиная с React [[19.2]]."],"en":["When an effect re-runs, React first runs the previous effect's [[cleanup|cleanup function]].","To actually cancel the request, I pass an [[AbortController]] signal to fetch and call abort in cleanup.","useEffectEvent has been stable since React [[19.2]]."]}},
41:{"lies":{"ru":["Если обернуть потребителя context в memo, он не будет перерендериваться при изменении value.","React Compiler работает только с React 19."],"en":["Wrapping a context consumer in memo stops it from re-rendering when the context value changes.","React Compiler only works with React 19."]},"cloze":{"ru":["Каждый потребитель context перерендеривается, когда value провайдера меняется по [[Object.is]].","memo пропускает рендер, только если props [[поверхностно равны|shallow-equal]] прошлым.","Для длинных списков [[виртуализация|virtualization|windowing]] рендерит только строки в видимой области плюс запас."],"en":["Every context consumer re-renders when the provider's value changes by [[Object.is]].","memo skips a render only when the props are [[shallow-equal|shallowly equal]] to last time.","For long lists, [[virtualization|windowing]] renders only the rows in the viewport plus some overscan."]}},
42:{"lies":{"ru":["Рекомендуемый способ сохранить отзывчивость ввода — обернуть setState самого поля ввода в startTransition.","Suspense показывает fallback, пока дочерний компонент загружает данные в useEffect."],"en":["The recommended way to keep typing responsive is to wrap the input's own setState in startTransition.","Suspense shows its fallback while a child component loads data in useEffect."]},"cloze":{"ru":["Transition может быть [[прерван]] более срочным обновлением, например вводом с клавиатуры.","Запросы, которые стартуют только после рендера родителя, дают [[водопад|лесенку|waterfall]]; ранний старт всех запросов называется [[render-as-you-fetch|предзагрузка|preloading]].","Пропсы через границу 'use client' должны быть [[сериализуемыми]], поэтому из функций разрешены только [[Server Functions]]."],"en":["A transition can be [[interrupted]] by a more urgent update like typing.","Fetches that start only after the parent renders create a [[waterfall|staircase]]; starting all requests early is called [[render-as-you-fetch|preloading]].","Props crossing the 'use client' boundary must be [[serializable]], so the only functions allowed are [[Server Functions]]."]}},
43:{"lies":{"ru":["Без reducer сеттер useOptimistic добавляет новое значение в конец существующего списка.","Несколько вызовов dispatch из useActionState выполняются параллельно, и побеждает тот, что завершился последним."],"en":["Without a reducer, the useOptimistic setter appends the new value to the existing list.","Multiple dispatch calls from useActionState run in parallel, and whichever resolves last wins."]},"cloze":{"ru":["useFormStatus читает статус только [[родительской|внешней]] формы, поэтому его вызывают в дочернем компоненте.","Без [[reducer|редьюсера]] сеттер useOptimistic [[заменяет|перезаписывает]] значение целиком.","Кнопка Stop вызывает abort у [[AbortController]], а клиент считает [[AbortError]] нормальным исходом."],"en":["useFormStatus only reads the status of a [[parent|enclosing]] form, so it has to be called in a child component.","Without a [[reducer]], the useOptimistic setter [[replaces|overwrites]] the whole value.","The Stop button calls abort on an [[AbortController]], and the client treats [[AbortError]] as a normal outcome."]}},
44:{"lies":{"ru":["При staleTime по умолчанию, равном нулю, TanStack Query прячет закешированные данные и показывает состояние загрузки при каждом монтировании.","Context перерисовывает только тех потребителей, которые читают изменившуюся часть значения."],"en":["With the default staleTime of zero, TanStack Query hides cached data and shows a loading state on every mount.","Context re-renders only the consumers that read the part of the value that changed."]},"cloze":{"ru":["[[gcTime]] задаёт, сколько неиспользуемый запрос живёт в кеше, а [[staleTime]] — сколько данные считаются свежими.","Всё, от чего зависит запрос, например фильтры, кладётся в [[query key|ключ запроса|queryKey]].","Фильтры, сортировка и активная вкладка живут в [[URL|search params]], тогда вид переживает перезагрузку и им можно поделиться."],"en":["[[gcTime]] controls how long an unused query stays in the cache, while [[staleTime]] controls how long data counts as fresh.","Everything the fetch depends on, like filters, goes into the [[query key|queryKey]].","Filters, sort and the active tab belong in the [[URL|search params]], so the view survives a reload and can be shared."]}},
45:{"lies":{"ru":["Чтение offsetHeight всегда дешёвое, потому что браузер просто возвращает закешированное значение, даже сразу после записи в DOM.","Скрипты с async, как и с defer, гарантированно выполняются в порядке документа после окончания парсинга."],"en":["Reading offsetHeight is always cheap because the browser just returns a cached value, even right after a DOM write.","Scripts with async, just like defer, are guaranteed to run in document order after parsing finishes."]},"cloze":{"ru":["Порядок конвейера: style, потом [[layout|reflow]], потом [[paint|отрисовка]], потом composite.","Чтение offsetHeight сразу после записи в DOM вызывает синхронный [[layout|reflow]].","Скрипт с [[defer]] качается параллельно и выполняется после парсинга в порядке документа."],"en":["The pipeline order is style, then [[layout|reflow]], then [[paint|painting]], then composite.","Reading offsetHeight right after a DOM write forces a synchronous [[layout|reflow]].","A script with [[defer]] downloads in parallel and runs after parsing, in document order."]}},
46:{"lies":{"ru":["INP измеряет только задержку перед запуском обработчика первого взаимодействия на странице.","Если Lighthouse показывает 100, страница гарантированно проходит Core Web Vitals в Search Console."],"en":["INP measures only the delay before the handler of the first interaction on the page starts running.","If Lighthouse shows 100, the page is guaranteed to pass Core Web Vitals in Search Console."]},"cloze":{"ru":["Хороший LCP это [[2,5|2.5]] секунды или меньше, хороший INP это [[200]] миллисекунд или меньше, хороший CLS это [[0,1|0.1]] или меньше.","В марте 2024 года INP заменил [[FID|First Input Delay]] в составе Core Web Vitals.","Полевые данные из [[CrUX|Chrome User Experience Report]] оцениваются на [[75-м|семьдесят пятом]] перцентиле."],"en":["A good LCP is [[2.5]] seconds or less, a good INP is [[200]] milliseconds or less, and a good CLS is [[0.1]] or less.","In March 2024, INP replaced [[FID|First Input Delay]] as a Core Web Vital.","Field data from [[CrUX|Chrome User Experience Report]] is scored at the [[75th|seventy-fifth]] percentile."]}},
47:{"lies":{"ru":["Cache-Control: no-cache запрещает браузеру вообще сохранять ответ.","HTTP/2 полностью устранил head-of-line blocking: потерянный пакет задерживает только свой поток."],"en":["Cache-Control: no-cache tells the browser not to store the response at all.","HTTP/2 fully eliminated head-of-line blocking: a lost packet only delays its own stream."]},"cloze":{"ru":["Браузер шлёт [[If-None-Match]] с сохранённым [[ETag]], и если ничего не изменилось, сервер отвечает [[304|304 Not Modified]].","Файлы с хешем в имени получают длинный max-age плюс [[immutable]], а HTML получает [[no-cache]].","HTTP/3 работает поверх [[QUIC]], поэтому потерянный пакет стопорит только свой поток."],"en":["The browser sends [[If-None-Match]] with the stored [[ETag]], and if nothing changed the server replies [[304|304 Not Modified]].","Hashed assets get a long max-age plus [[immutable]], while the HTML gets [[no-cache]].","HTTP/3 runs over [[QUIC]], so a lost packet stalls only its own stream."]}},
48:{"lies":{"ru":["SameSite=Lax стоит по умолчанию во всех основных браузерах, поэтому явно задавать его не нужно.","Если CORS-политика не разрешает evil.com, то POST-форма с evil.com вообще не дойдёт до нашего сервера."],"en":["SameSite=Lax is the default in all major browsers, so there's no need to set it explicitly.","If our CORS policy doesn't allow evil.com, a form POST from evil.com never reaches our server."]},"cloze":{"ru":["Строгий CSP использует в script-src [[nonce|одноразовое значение]] на каждый запрос вместе с 'strict-dynamic'.","С SameSite=[[Lax]] cookie отправляется при top-level GET-навигации, но не при кросс-сайтовых POST.","Картинка в markdown с URL атакующего превращает prompt injection в канал [[утечки данных|утечки|утечки информации]]."],"en":["A strict CSP puts a per-request [[nonce|nonce value]] in script-src together with 'strict-dynamic'.","With SameSite=[[Lax]], the cookie is sent on top-level GET navigations but not on cross-site POSTs.","A markdown image pointing at an attacker URL turns prompt injection into a channel for [[exfiltration|data exfiltration|data leaks]]."]}},
49:{"lies":{"ru":["Если добавить role=\"button\" на div, он станет фокусируемым и начнёт активироваться с клавиатуры.","Если axe и Lighthouse не нашли ни одной проблемы, страница доступна."],"en":["Adding role=\"button\" to a div makes it focusable and keyboard-activatable.","If axe and Lighthouse report zero issues, the page is accessible."]},"cloze":{"ru":["Первое правило ARIA: не используй ARIA, если нативный [[элемент|HTML-элемент]] справляется.","При закрытии модалки фокус нужно вернуть на [[триггер|элемент, который её открыл|кнопку открытия]].","Для стриминга я использую регион aria-live=\"[[polite]]\" и объявляю ответ по [[завершении|окончании]]."],"en":["The first rule of ARIA: don't use ARIA if a native [[element|HTML element]] does the job.","When the modal closes, return focus to the [[trigger|element that opened it|opening button]].","For streaming output I use an aria-live=\"[[polite]]\" region and announce the response once it's [[complete|finished|done]]."]}},
50:{"lies":{"ru":["EventSource подходит для чата: через него можно отправить POST с историей сообщений и заголовком Authorization.","Вызов abort() на клиенте сам останавливает генерацию LLM на сервере, серверный код для этого не нужен."],"en":["EventSource works fine for chat: you can POST the message history through it with an Authorization header.","Calling abort() on the client stops the LLM generation on the server by itself, no server code needed."]},"cloze":{"ru":["EventSource поддерживает только [[GET]]-запросы и не может ставить свои [[заголовки|headers]].","При переподключении браузер шлёт заголовок [[Last-Event-ID]], чтобы сервер дослал пропущенные события.","Декодируйте чанки через TextDecoder с [[stream: true|stream:true]], чтобы многобайтовый символ на стыке не побился, а запрос отменяйте через [[AbortController]]."],"en":["EventSource only supports [[GET]] requests and can't set custom [[headers]].","On reconnect the browser sends a [[Last-Event-ID]] header so the server can replay missed events.","Decode chunks with TextDecoder and [[stream: true|stream:true]] so a split multi-byte character isn't corrupted, and cancel with [[AbortController]]."]}}
};

